INSERT INTO `platform_exception_rule`
  (`id`, `rule_code`, `rule_name`, `domain_code`, `rule_desc`, `level`, `rule_kind`, `escalation_of_rule_code`, `trigger_type`, `cron_expression`, `listen_entities`, `pipeline_json`, `threshold_json`, `owner_selector`, `resolve_policy`, `storm_json`, `biz_type`, `mutual_exclusive_group`, `flow_template`, `biz_url_template`, `enable_status`, `engine_version`, `version`, `seq_no`, `creator`, `creator_name`) VALUES
('95294b2e6c707e97355a33961a0f2851', 'EXC-BL-004', '正本提单逾期未回收', 'BL', '判定：到港（R9）+30 天，正本约定份数 >0 且提单放货状态未回填（未回收近似）。\n恢复：回收登记（cargo_status 回填至回收/放货完成态）。\n口径：按实际表——应回收份数=il_eco.bill_lading_count（提单份数）；已回收份数与回收时间全库无专用字段，按 il_order_bol.cargo_status/bol_status 状态近似（值域校准前置：cargo_status 回填即视为已处理）。', 'P0', 'ALERT', NULL, 'SCAN', '0 0/15 * * * *', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $sql.query(`\\n  SELECT ''BOL'' AS biz_type,\\n         b.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         r9.node_time AS r9_time,\\n         e.bill_lading_count AS bill_lading_count,\\n         b.bol_status AS bol_status, b.cargo_status AS cargo_status,\\n         r9.node_time AS anchor_time\\n  FROM ob.il_order_bol b\\n  JOIN ob.il_eco e ON e.id = b.order_id\\n  JOIN ob.il_eco_route r9 ON r9.eco_id = e.id AND r9.code = ''9''\\n  WHERE b.del_status = 0 AND e.del_status = 0\\n    AND IFNULL(e.bill_lading_count, 0) > 0\\n    AND r9.node_time <= DATE_SUB(NOW(), INTERVAL :days DAY)\\n    AND b.cargo_status IS NULL\\n`, $params)\\nreturn rows.filter(r => $gl.fn.daysSince(r.r9_time) >= $params.days\\n    && r.bill_lading_count > 0 && r.cargo_status == null)"}]}', '{"days":30}', '{"handlers":[{"type":"BIZ_FIELD"},{"type":"DEPT_ROLE","roleCode":"il_fgs_czy","org":{"scope":"BIZ_ORG"}}],"cc":[{"type":"DEPT_ROLE","roleCode":"il_zgs_cwjl","org":{"scope":"BIZ_ORG"}}]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'BOL', NULL, 'STANDARD', '/fms/booking-release/{bizId}', 1, NULL, 1, 1, 'system', '系统初始化'),
('db5503c7a5fb32497757b04505df0456', 'EXC-BL-004-E1', '正本提单逾期未回收·1 级升级', 'BL', '升级规则：EXC-BL-004 在途且滞留 ≥ 4h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-BL-004', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-BL-004（原条件），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''BOL'' AS biz_type,\\n         b.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         r9.node_time AS r9_time,\\n         e.bill_lading_count AS bill_lading_count,\\n         b.bol_status AS bol_status, b.cargo_status AS cargo_status,\\n         r9.node_time AS anchor_time\\n  FROM ob.il_order_bol b\\n  JOIN ob.il_eco e ON e.id = b.order_id\\n  JOIN ob.il_eco_route r9 ON r9.eco_id = e.id AND r9.code = ''9''\\n  WHERE b.del_status = 0 AND e.del_status = 0\\n    AND IFNULL(e.bill_lading_count, 0) > 0\\n    AND r9.node_time <= DATE_SUB(NOW(), INTERVAL :days DAY)\\n    AND b.cargo_status IS NULL\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-BL-004）----\\n  const base = $gl.fn.daysSince(r.r9_time) >= $params.days\\n      && r.bill_lading_count > 0 && r.cargo_status == null\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"days":30,"escalateAfterHours":4}', '{"handlers":[{"type":"ORG_TREE_UP","level":1,"roleCode":"il_fgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'BOL', NULL, 'STANDARD', '/fms/booking-release/{bizId}', 1, NULL, 1, 2, 'system', '系统初始化'),
('045cd134e011272636116c821591a617', 'EXC-BL-004-E2', '正本提单逾期未回收·2 级升级', 'BL', '升级规则：EXC-BL-004 在途且滞留 ≥ 8h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-BL-004-E1', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-BL-004（原条件），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''BOL'' AS biz_type,\\n         b.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         r9.node_time AS r9_time,\\n         e.bill_lading_count AS bill_lading_count,\\n         b.bol_status AS bol_status, b.cargo_status AS cargo_status,\\n         r9.node_time AS anchor_time\\n  FROM ob.il_order_bol b\\n  JOIN ob.il_eco e ON e.id = b.order_id\\n  JOIN ob.il_eco_route r9 ON r9.eco_id = e.id AND r9.code = ''9''\\n  WHERE b.del_status = 0 AND e.del_status = 0\\n    AND IFNULL(e.bill_lading_count, 0) > 0\\n    AND r9.node_time <= DATE_SUB(NOW(), INTERVAL :days DAY)\\n    AND b.cargo_status IS NULL\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-BL-004）----\\n  const base = $gl.fn.daysSince(r.r9_time) >= $params.days\\n      && r.bill_lading_count > 0 && r.cargo_status == null\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"days":30,"escalateAfterHours":8}', '{"handlers":[{"type":"ORG_TREE_UP","level":2,"roleCode":"il_zgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'BOL', NULL, 'STANDARD', '/fms/booking-release/{bizId}', 1, NULL, 1, 3, 'system', '系统初始化'),
('42b0def329a26fbc742c361d97a2406e', 'EXC-BL-005', '未收款放单申请', 'BL', '时点：放单申请提交（il_order_bol_grant 创建）。\n判定：订单未核销应收 > 0（0 容差）。\n恢复：欠款核销（费用行 amount_not_written_off 归零）/ 申请撤回 / 财务负责人特批留痕。\n口径：按实际表——未核销=SUM(il_so_container_fee_detail.amount_not_written_off) WHERE order_id=g.order_id AND fee_type=''1''（账单级金额为多币种 JSON 不可比较）；单号=order_req_no、状态=biz_status（''已撤回'' 值校准前置）；核销回写费用行触发复评（listen RELATED=il_so_container_fee_detail）。', 'P0', 'ALERT', NULL, 'BOTH', '0 0/15 * * * *', '[{"entity":"il_order_bol_grant","operations":["insert"],"role":"PRIMARY"},{"entity":"il_so_container_fee_detail","operations":["update"],"role":"RELATED","refField":"order_id"}]', '{"steps":[{"name":"judge","lang":"js","content":"// 同一管道：变更触发（$ctx.bizId 单对象）/ 定时扫描（窗口全量）二选一\\nconst isCheck = $ctx.bizId != null\\nconst sql = isCheck ? `\\n  SELECT ''BOL_GRANT'' AS biz_type,\\n         g.id AS biz_id, g.order_req_no AS biz_label,\\n         g.customer_id AS customer_id, cu.name AS customer_name,\\n         g.creator AS owner_id, g.creator_name AS owner_name,\\n         IFNULL((SELECT SUM(f.amount_not_written_off)\\n                 FROM ob.il_so_container_fee_detail f\\n                 WHERE f.order_id = g.order_id AND f.del_status = 0\\n                   AND f.fee_type = ''1''), 0) AS not_written_off,\\n         g.order_id AS order_id\\n  FROM ob.il_order_bol_grant g\\n  LEFT JOIN ob.il_cooperating_org cu ON cu.id = g.customer_id\\n  WHERE g.id = :bizId\\n    AND g.del_status = 0\\n    AND (g.biz_status IS NULL OR g.biz_status <> ''已撤回'')\\n` : `\\n  SELECT ''BOL_GRANT'' AS biz_type,\\n         g.id AS biz_id, g.order_req_no AS biz_label,\\n         g.customer_id AS customer_id, cu.name AS customer_name,\\n         g.creator AS owner_id, g.creator_name AS owner_name,\\n         IFNULL((SELECT SUM(f.amount_not_written_off)\\n                 FROM ob.il_so_container_fee_detail f\\n                 WHERE f.order_id = g.order_id AND f.del_status = 0\\n                   AND f.fee_type = ''1''), 0) AS not_written_off,\\n         g.order_id AS order_id\\n  FROM ob.il_order_bol_grant g\\n  LEFT JOIN ob.il_cooperating_org cu ON cu.id = g.customer_id\\n  WHERE g.del_status = 0\\n    AND (g.biz_status IS NULL OR g.biz_status <> ''已撤回'')\\n    AND g.create_at >= DATE_SUB(NOW(), INTERVAL :windowDays DAY)\\n`\\nreturn $sql.query(sql, { ...$params, bizId: $ctx.bizId })\\n    .filter(r => r.not_written_off > 0)"}]}', '{"windowDays":90}', '{"handlers":[{"type":"DEPT_ROLE","roleCode":"il_zgs_cwjl","org":{"scope":"BIZ_ORG"}}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'BOL_GRANT', NULL, 'INTERCEPT', '/fms/booking-release/{bizId}?tab=grant', 1, NULL, 1, 4, 'system', '系统初始化'),
('a26f76980dab1b004587364bbc9732eb', 'EXC-BL-005-E1', '未收款放单申请·1 级升级', 'BL', '升级规则：EXC-BL-005 在途且滞留 ≥ 4h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-BL-005', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-BL-005（扫描口径），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''BOL_GRANT'' AS biz_type,\\n         g.id AS biz_id, g.order_req_no AS biz_label,\\n         g.customer_id AS customer_id, cu.name AS customer_name,\\n         g.creator AS owner_id, g.creator_name AS owner_name,\\n         IFNULL((SELECT SUM(f.amount_not_written_off)\\n                 FROM ob.il_so_container_fee_detail f\\n                 WHERE f.order_id = g.order_id AND f.del_status = 0\\n                   AND f.fee_type = ''1''), 0) AS not_written_off,\\n         g.order_id AS order_id\\n  FROM ob.il_order_bol_grant g\\n  LEFT JOIN ob.il_cooperating_org cu ON cu.id = g.customer_id\\n  WHERE g.del_status = 0\\n    AND (g.biz_status IS NULL OR g.biz_status <> ''已撤回'')\\n    AND g.create_at >= DATE_SUB(NOW(), INTERVAL :windowDays DAY)\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-BL-005）----\\n  const base = r.not_written_off > 0\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"windowDays":90,"escalateAfterHours":4}', '{"handlers":[{"type":"ORG_TREE_UP","level":1,"roleCode":"il_fgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'BOL_GRANT', NULL, 'INTERCEPT', '/fms/booking-release/{bizId}?tab=grant', 1, NULL, 1, 5, 'system', '系统初始化'),
('8e4d4bcb87d0cd88c996560a945265c8', 'EXC-BL-005-E2', '未收款放单申请·2 级升级', 'BL', '升级规则：EXC-BL-005 在途且滞留 ≥ 8h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-BL-005-E1', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-BL-005（扫描口径），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''BOL_GRANT'' AS biz_type,\\n         g.id AS biz_id, g.order_req_no AS biz_label,\\n         g.customer_id AS customer_id, cu.name AS customer_name,\\n         g.creator AS owner_id, g.creator_name AS owner_name,\\n         IFNULL((SELECT SUM(f.amount_not_written_off)\\n                 FROM ob.il_so_container_fee_detail f\\n                 WHERE f.order_id = g.order_id AND f.del_status = 0\\n                   AND f.fee_type = ''1''), 0) AS not_written_off,\\n         g.order_id AS order_id\\n  FROM ob.il_order_bol_grant g\\n  LEFT JOIN ob.il_cooperating_org cu ON cu.id = g.customer_id\\n  WHERE g.del_status = 0\\n    AND (g.biz_status IS NULL OR g.biz_status <> ''已撤回'')\\n    AND g.create_at >= DATE_SUB(NOW(), INTERVAL :windowDays DAY)\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-BL-005）----\\n  const base = r.not_written_off > 0\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"windowDays":90,"escalateAfterHours":8}', '{"handlers":[{"type":"ORG_TREE_UP","level":2,"roleCode":"il_zgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'BOL_GRANT', NULL, 'INTERCEPT', '/fms/booking-release/{bizId}?tab=grant', 1, NULL, 1, 6, 'system', '系统初始化'),
('40a0bbec9b13f74c02371beaa85be934', 'EXC-CUS-002', '冻结客户下单', 'CUS', '时点：新建委托。\n判定：客户在黑名单（il_cooperating_org_blocked.in_blocked=1）→ 即触发。\n恢复：解冻 + 订单特批留痕。\n口径：按实际表——客户外键=cooperating_org_id（blocked 表无 customer_id/order 外键）；冻结状态变化由扫描周期覆盖（blocked 表无订单外键，无法作 RELATED 复评入口）；windowDays 为下单回看窗口。', 'P0', 'ALERT', NULL, 'BOTH', '0 0/15 * * * *', '[{"entity":"il_eco","operations":["insert"],"role":"PRIMARY"}]', '{"steps":[{"name":"judge","lang":"js","content":"// 同一管道：变更触发（$ctx.bizId 单对象）/ 定时扫描（窗口全量）二选一\\nconst isCheck = $ctx.bizId != null\\nconst sql = isCheck ? `\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.creator AS owner_id, e.creator_name AS owner_name,\\n         bk.in_blocked AS in_blocked, bk.remark AS blocked_remark, bk.block_time AS block_time\\n  FROM ob.il_eco e\\n  JOIN ob.il_cooperating_org_blocked bk\\n    ON bk.cooperating_org_id = e.customer_id AND bk.del_status = 0\\n  WHERE e.id = :bizId\\n    AND bk.in_blocked = 1\\n` : `\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.creator AS owner_id, e.creator_name AS owner_name,\\n         bk.in_blocked AS in_blocked, bk.remark AS blocked_remark, bk.block_time AS block_time\\n  FROM ob.il_eco e\\n  JOIN ob.il_cooperating_org_blocked bk\\n    ON bk.cooperating_org_id = e.customer_id AND bk.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.create_at >= DATE_SUB(NOW(), INTERVAL :windowDays DAY)\\n    AND bk.in_blocked = 1\\n`\\nreturn $sql.query(sql, { ...$params, bizId: $ctx.bizId })\\n    .filter(r => r.in_blocked == 1)"}]}', '{"windowDays":7}', '{"handlers":[{"type":"DEPT_ROLE","roleCode":"il_zgs_cwjl","org":{"scope":"BIZ_ORG"}}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'CUSTOMER', NULL, 'INTERCEPT', '/fms/customer/{bizId}', 1, NULL, 1, 7, 'system', '系统初始化'),
('7a287221a8027f478b60b9c5ea3dba69', 'EXC-CUS-002-E1', '冻结客户下单·1 级升级', 'CUS', '升级规则：EXC-CUS-002 在途且滞留 ≥ 4h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-CUS-002', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-CUS-002（扫描口径），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.creator AS owner_id, e.creator_name AS owner_name,\\n         bk.in_blocked AS in_blocked, bk.remark AS blocked_remark, bk.block_time AS block_time\\n  FROM ob.il_eco e\\n  JOIN ob.il_cooperating_org_blocked bk\\n    ON bk.cooperating_org_id = e.customer_id AND bk.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.create_at >= DATE_SUB(NOW(), INTERVAL :windowDays DAY)\\n    AND bk.in_blocked = 1\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-CUS-002）----\\n  const base = r.in_blocked == 1\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"windowDays":7,"escalateAfterHours":4}', '{"handlers":[{"type":"ORG_TREE_UP","level":1,"roleCode":"il_fgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'CUSTOMER', NULL, 'INTERCEPT', '/fms/customer/{bizId}', 1, NULL, 1, 8, 'system', '系统初始化'),
('289f7eb730556331f4001900245c2ebc', 'EXC-CUS-002-E2', '冻结客户下单·2 级升级', 'CUS', '升级规则：EXC-CUS-002 在途且滞留 ≥ 8h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-CUS-002-E1', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-CUS-002（扫描口径），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.creator AS owner_id, e.creator_name AS owner_name,\\n         bk.in_blocked AS in_blocked, bk.remark AS blocked_remark, bk.block_time AS block_time\\n  FROM ob.il_eco e\\n  JOIN ob.il_cooperating_org_blocked bk\\n    ON bk.cooperating_org_id = e.customer_id AND bk.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.create_at >= DATE_SUB(NOW(), INTERVAL :windowDays DAY)\\n    AND bk.in_blocked = 1\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-CUS-002）----\\n  const base = r.in_blocked == 1\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"windowDays":7,"escalateAfterHours":8}', '{"handlers":[{"type":"ORG_TREE_UP","level":2,"roleCode":"il_zgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'CUSTOMER', NULL, 'INTERCEPT', '/fms/customer/{bizId}', 1, NULL, 1, 9, 'system', '系统初始化'),
('791eafe09cd2c6725dbcc13148e5c69b', 'EXC-FIN-008', '长期挂账', 'FIN', '判定：应收最早推算到期日（出账日 + 客户账期）距今 ≥180 天，且期间无回款流水（il_bill_write_off 到账/核销时间）。\n恢复：回款核销，或坏账核销审批通过。\n衔接：与 FIN-001 重叠时升级为 FIN-008。\n口径：按实际表结构——客户=unit_of_account（财务域无 customer_id）；应收未核销=费用行（il_so_container_fee_detail fee_type=''1'' 且 amount_not_written_off>0，账单级金额为多币种 JSON 不可比较）；到期日无实表列，按出账日（biz_status_time/create_at）+ 账期（il_customer_settle_contract.settlement_date）推算。', 'P0', 'ALERT', NULL, 'SCAN', '0 0/15 * * * *', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $sql.query(`\\n  SELECT ''BILL'' AS biz_type,\\n         b.unit_of_account AS biz_id, b.unit_of_account_name AS biz_label,\\n         b.unit_of_account AS customer_id, b.unit_of_account_name AS customer_name,\\n         b.dept_id AS owner_id, b.company_id AS owner_name,\\n         MIN(DATE_ADD(COALESCE(b.biz_status_time, b.create_at),\\n             INTERVAL IFNULL(sc.settlement_date, 0) DAY)) AS earliest_due_date,\\n         MIN(DATE_ADD(COALESCE(b.biz_status_time, b.create_at),\\n             INTERVAL IFNULL(sc.settlement_date, 0) DAY)) AS anchor_time\\n  FROM ob.il_bill b\\n  LEFT JOIN ob.il_customer_settle_contract sc\\n    ON sc.cooperating_org_id = b.unit_of_account AND sc.del_status = 0\\n  WHERE b.del_status = 0\\n    AND EXISTS (\\n      SELECT 1 FROM ob.il_so_container_fee_detail f\\n      WHERE f.bill_id = b.id AND f.del_status = 0\\n        AND f.fee_type = ''1''\\n        AND f.amount_not_written_off > 0\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1 FROM ob.il_bill_write_off w\\n      WHERE w.del_status = 0\\n        AND w.unit_of_account = b.unit_of_account\\n        AND COALESCE(w.to_the_account_time, w.write_off_time)\\n            >= DATE_SUB(NOW(), INTERVAL :days DAY)\\n    )\\n  GROUP BY b.unit_of_account, b.unit_of_account_name, b.dept_id, b.company_id\\n`, $params)\\nreturn rows.filter(r => $gl.fn.daysSince(r.earliest_due_date) >= $params.days)"}]}', '{"days":180}', '{"handlers":[{"type":"DEPT_ROLE","roleCode":"il_zgs_cw","org":{"scope":"BIZ_ORG"}}],"cc":[{"type":"DEPT_ROLE","roleCode":"il_zgs_cwjl","org":{"scope":"BIZ_ORG"}}]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'BILL', 'FIN_001_008', 'STANDARD', '/fms/finance/{bizId}', 1, NULL, 1, 10, 'system', '系统初始化'),
('b02ca52415010357be97975e70c30544', 'EXC-FIN-008-E1', '长期挂账·1 级升级', 'FIN', '升级规则：EXC-FIN-008 在途且滞留 ≥ 4h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-FIN-008', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-FIN-008（原条件），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''BILL'' AS biz_type,\\n         b.unit_of_account AS biz_id, b.unit_of_account_name AS biz_label,\\n         b.unit_of_account AS customer_id, b.unit_of_account_name AS customer_name,\\n         b.dept_id AS owner_id, b.company_id AS owner_name,\\n         MIN(DATE_ADD(COALESCE(b.biz_status_time, b.create_at),\\n             INTERVAL IFNULL(sc.settlement_date, 0) DAY)) AS earliest_due_date,\\n         MIN(DATE_ADD(COALESCE(b.biz_status_time, b.create_at),\\n             INTERVAL IFNULL(sc.settlement_date, 0) DAY)) AS anchor_time\\n  FROM ob.il_bill b\\n  LEFT JOIN ob.il_customer_settle_contract sc\\n    ON sc.cooperating_org_id = b.unit_of_account AND sc.del_status = 0\\n  WHERE b.del_status = 0\\n    AND EXISTS (\\n      SELECT 1 FROM ob.il_so_container_fee_detail f\\n      WHERE f.bill_id = b.id AND f.del_status = 0\\n        AND f.fee_type = ''1''\\n        AND f.amount_not_written_off > 0\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1 FROM ob.il_bill_write_off w\\n      WHERE w.del_status = 0\\n        AND w.unit_of_account = b.unit_of_account\\n        AND COALESCE(w.to_the_account_time, w.write_off_time)\\n            >= DATE_SUB(NOW(), INTERVAL :days DAY)\\n    )\\n  GROUP BY b.unit_of_account, b.unit_of_account_name, b.dept_id, b.company_id\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-FIN-008）----\\n  const base = $gl.fn.daysSince(r.earliest_due_date) >= $params.days\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"days":180,"escalateAfterHours":4}', '{"handlers":[{"type":"ORG_TREE_UP","level":1,"roleCode":"il_fgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'BILL', NULL, 'STANDARD', '/fms/finance/{bizId}', 1, NULL, 1, 11, 'system', '系统初始化'),
('be63d058afedc27df50e356d23eb77be', 'EXC-FIN-008-E2', '长期挂账·2 级升级', 'FIN', '升级规则：EXC-FIN-008 在途且滞留 ≥ 8h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-FIN-008-E1', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-FIN-008（原条件），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''BILL'' AS biz_type,\\n         b.unit_of_account AS biz_id, b.unit_of_account_name AS biz_label,\\n         b.unit_of_account AS customer_id, b.unit_of_account_name AS customer_name,\\n         b.dept_id AS owner_id, b.company_id AS owner_name,\\n         MIN(DATE_ADD(COALESCE(b.biz_status_time, b.create_at),\\n             INTERVAL IFNULL(sc.settlement_date, 0) DAY)) AS earliest_due_date,\\n         MIN(DATE_ADD(COALESCE(b.biz_status_time, b.create_at),\\n             INTERVAL IFNULL(sc.settlement_date, 0) DAY)) AS anchor_time\\n  FROM ob.il_bill b\\n  LEFT JOIN ob.il_customer_settle_contract sc\\n    ON sc.cooperating_org_id = b.unit_of_account AND sc.del_status = 0\\n  WHERE b.del_status = 0\\n    AND EXISTS (\\n      SELECT 1 FROM ob.il_so_container_fee_detail f\\n      WHERE f.bill_id = b.id AND f.del_status = 0\\n        AND f.fee_type = ''1''\\n        AND f.amount_not_written_off > 0\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1 FROM ob.il_bill_write_off w\\n      WHERE w.del_status = 0\\n        AND w.unit_of_account = b.unit_of_account\\n        AND COALESCE(w.to_the_account_time, w.write_off_time)\\n            >= DATE_SUB(NOW(), INTERVAL :days DAY)\\n    )\\n  GROUP BY b.unit_of_account, b.unit_of_account_name, b.dept_id, b.company_id\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-FIN-008）----\\n  const base = $gl.fn.daysSince(r.earliest_due_date) >= $params.days\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"days":180,"escalateAfterHours":8}', '{"handlers":[{"type":"ORG_TREE_UP","level":2,"roleCode":"il_zgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'BILL', NULL, 'STANDARD', '/fms/finance/{bizId}', 1, NULL, 1, 12, 'system', '系统初始化'),
('67c22f0d31f40075eafa5568260a7fc6', 'EXC-ODR-002', '截关前未进港', 'ODR', '判定：截关时刻（cut_off_delivery，缺失取 cy_closing_time）−12h ≤ now，无进港记录（ot_container_status.gitm_time 为空）且未离港（无 R7）。\n恢复：进港（gitm_time 写入）或 R7 写入。\n口径：进港时间以 ob_portal.ot_container_status.gitm_time 为准（按 bill_no=mbl_no + container_no 关联，与 ODR-003/004 同源）；不用附件回执字典。', 'P0', 'ALERT', NULL, 'SCAN', '0 0/15 * * * *', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         e.mbl_no AS mbl_no, e.container_no AS container_no,\\n         COALESCE(e.cut_off_delivery, e.cy_closing_time) AS cut_off_time,\\n         TIMESTAMPDIFF(HOUR, NOW(), COALESCE(e.cut_off_delivery, e.cy_closing_time)) AS hours_to_cut,\\n         cs.gitm_time AS gitm_time,\\n         EXISTS(SELECT 1 FROM ob.il_eco_route r WHERE r.eco_id = e.id AND r.code = ''7'') AS sailed\\n  FROM ob.il_eco e\\n  LEFT JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0 AND e.biz_type < 5\\n    AND e.container_no IS NOT NULL AND TRIM(e.container_no) <> ''''\\n    AND COALESCE(e.cut_off_delivery, e.cy_closing_time)\\n        BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL :leadHours HOUR)\\n`, $params)\\nreturn rows.filter(r => r.hours_to_cut <= $params.leadHours\\n    && r.gitm_time == null && !r.sailed)"}]}', '{"leadHours":12}', '{"handlers":[{"type":"BIZ_FIELD"},{"type":"DEPT_ROLE","roleCode":"il_fgs_czy","org":{"scope":"BIZ_ORG"}}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_002_017', 'STANDARD', '/fms/so/{bizId}', 1, NULL, 1, 13, 'system', '系统初始化'),
('c8a4e51e3ff422fb943016fab46d03ea', 'EXC-ODR-002-E1', '截关前未进港·1 级升级', 'ODR', '升级规则：EXC-ODR-002 在途且滞留 ≥ 4h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-ODR-002', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-ODR-002（原条件），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         e.mbl_no AS mbl_no, e.container_no AS container_no,\\n         COALESCE(e.cut_off_delivery, e.cy_closing_time) AS cut_off_time,\\n         TIMESTAMPDIFF(HOUR, NOW(), COALESCE(e.cut_off_delivery, e.cy_closing_time)) AS hours_to_cut,\\n         cs.gitm_time AS gitm_time,\\n         EXISTS(SELECT 1 FROM ob.il_eco_route r WHERE r.eco_id = e.id AND r.code = ''7'') AS sailed\\n  FROM ob.il_eco e\\n  LEFT JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0 AND e.biz_type < 5\\n    AND e.container_no IS NOT NULL AND TRIM(e.container_no) <> ''''\\n    AND COALESCE(e.cut_off_delivery, e.cy_closing_time)\\n        BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL :leadHours HOUR)\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-ODR-002）----\\n  const base = r.hours_to_cut <= $params.leadHours\\n      && r.gitm_time == null && !r.sailed\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"leadHours":12,"escalateAfterHours":4}', '{"handlers":[{"type":"ORG_TREE_UP","level":1,"roleCode":"il_fgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 1, NULL, 1, 14, 'system', '系统初始化'),
('28d367606d85822afd9c34a62fca1898', 'EXC-ODR-002-E2', '截关前未进港·2 级升级', 'ODR', '升级规则：EXC-ODR-002 在途且滞留 ≥ 8h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-ODR-002-E1', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-ODR-002（原条件），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         e.mbl_no AS mbl_no, e.container_no AS container_no,\\n         COALESCE(e.cut_off_delivery, e.cy_closing_time) AS cut_off_time,\\n         TIMESTAMPDIFF(HOUR, NOW(), COALESCE(e.cut_off_delivery, e.cy_closing_time)) AS hours_to_cut,\\n         cs.gitm_time AS gitm_time,\\n         EXISTS(SELECT 1 FROM ob.il_eco_route r WHERE r.eco_id = e.id AND r.code = ''7'') AS sailed\\n  FROM ob.il_eco e\\n  LEFT JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0 AND e.biz_type < 5\\n    AND e.container_no IS NOT NULL AND TRIM(e.container_no) <> ''''\\n    AND COALESCE(e.cut_off_delivery, e.cy_closing_time)\\n        BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL :leadHours HOUR)\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-ODR-002）----\\n  const base = r.hours_to_cut <= $params.leadHours\\n      && r.gitm_time == null && !r.sailed\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"leadHours":12,"escalateAfterHours":8}', '{"handlers":[{"type":"ORG_TREE_UP","level":2,"roleCode":"il_zgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 1, NULL, 1, 15, 'system', '系统初始化'),
('2cb62c36560e345ac61dc0e3b4281f88', 'EXC-ODR-003', '到港后未提柜', 'ODR', '判定：到港可提货（pdba_time）后 ≥2 天仍未提柜（stcs_time 为空）。\n恢复：提柜回填（stcs_time / pick_up_date）。\n口径：转写自既有箱货预警程序（ot_container_status 箱轨迹，阈值参数化）；SOC 自有箱排除。', 'P1', 'ALERT', NULL, 'SCAN', '0 0 * * * *', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         e.mbl_no AS mbl_no, cs.container_no AS container_no,\\n         cs.pdba_time AS pdba_time, cs.stcs_time AS stcs_time,\\n         cs.pdba_time AS anchor_time,\\n         TIMESTAMPDIFF(HOUR, cs.pdba_time, NOW()) AS anchor_elapsed\\n  FROM {db-router}.il_eco e\\n  JOIN {db-router}.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  LEFT JOIN (\\n    SELECT oc.order_id, oc.container_no,\\n           MAX(CASE WHEN UPPER(TRIM(oc.container_ownership_type)) = ''SOC'' THEN 1 ELSE 0 END) AS has_soc\\n    FROM {db-router}.il_order_container oc\\n    WHERE oc.del_status = 0\\n    GROUP BY oc.order_id, oc.container_no\\n  ) ocm ON ocm.order_id = e.id AND ocm.container_no = e.container_no\\n  WHERE e.del_status = 0 AND e.biz_type < 5\\n    AND (e.ata IS NULL OR e.ata >= DATE_SUB(NOW(), INTERVAL 2 MONTH))\\n    AND e.container_no IS NOT NULL AND TRIM(e.container_no) <> ''''\\n    AND COALESCE(ocm.has_soc, 0) = 0\\n    AND cs.pdba_time IS NOT NULL AND cs.stcs_time IS NULL\\n`, $params)\\nreturn rows.filter(r => $gl.fn.daysSince(r.pdba_time) >= $params.days)"}]}', '{"days":2}', '{"handlers":[{"type":"BIZ_FIELD"},{"type":"DEPT_ROLE","roleCode":"il_fgs_czy","org":{"scope":"BIZ_ORG"}}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_003_013', 'STANDARD', '/fms/so/{bizId}', 1, NULL, 1, 16, 'system', '系统初始化'),
('79b09a87c939dd7463d1dfcfcd818780', 'EXC-ODR-004', '免箱期将超', 'ODR', '范围：已提柜未还箱。\n判定：提柜（stcs_time）后 ≥4 天仍未还箱（rcve_time / return_case_date 均为空）。\n恢复：还箱回填（rcve_time / return_case_date）。\n衔接：超期转 EXC-TRN-005。\n口径：转写自既有箱货预警程序（以提柜后 N 天未还箱近似免箱超期，阈值参数化）；SOC 自有箱排除。', 'P0', 'ALERT', NULL, 'SCAN', '0 0/15 * * * *', NULL, '{"title":"提柜后超期未还箱，滞箱费风险","steps":[{"name":"judge","lang":"js","content":"const rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id AS customer_id, e.customer_name AS customer_name,\\n         e.operator_id AS owner_id, e.operator_name AS owner_name,\\n         e.mbl_no AS mbl_no, cs.container_no AS container_no,\\n         e.last_free_day AS last_free_day,\\n         cs.stcs_time AS stcs_time, cs.rcve_time AS rcve_time,\\n         cs.stcs_time AS anchor_time,\\n         TIMESTAMPDIFF(HOUR, cs.stcs_time, NOW()) AS anchor_elapsed\\n  FROM {db-router}.il_eco e\\n  JOIN {db-router}.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  LEFT JOIN (\\n    SELECT oc.order_id, oc.container_no,\\n           MAX(CASE WHEN UPPER(TRIM(oc.container_ownership_type)) = ''SOC'' THEN 1 ELSE 0 END) AS has_soc\\n    FROM {db-router}.il_order_container oc\\n    WHERE oc.del_status = 0\\n    GROUP BY oc.order_id, oc.container_no\\n  ) ocm ON ocm.order_id = e.id AND ocm.container_no = e.container_no\\n  WHERE e.del_status = 0 AND e.biz_type < 5\\n    AND (e.ata IS NULL OR e.ata >= DATE_SUB(NOW(), INTERVAL 2 MONTH))\\n    AND e.container_no IS NOT NULL AND TRIM(e.container_no) <> ''''\\n    AND COALESCE(ocm.has_soc, 0) = 0\\n    AND cs.stcs_time IS NOT NULL\\n    AND COALESCE(cs.rcve_time, e.return_case_date) IS NULL\\n`, $params)\\nreturn rows.filter(r => $gl.fn.daysSince(r.stcs_time) >= $params.days)"}]}', '{"days":4}', '{"handlers":[{"type":"BIZ_FIELD"},{"type":"DEPT_ROLE","roleCode":"il_fgs_czy","org":{"scope":"BIZ_ORG"}}],"cc":[{"type":"DEPT_ROLE","roleCode":"il_fgs_zjl","org":{"scope":"BIZ_ORG"}}]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_004_TRN_005', 'STANDARD', '/fms/so/{bizId}', 1, NULL, 1, 17, 'system', '系统初始化'),
('431f7d1f0d54d5f27a162bcd8201c3e0', 'EXC-SLOT-004', '船司甩柜/取消', 'SLOT', '判定：舱位取消记录产生（il_space_cancel.insert，cancel_status 为取消值）→ 即触发。\n恢复：改配完成留痕。\n口径：按实际表——il_space 无 biz_status/客户关联，改用 il_space_cancel（取消记录）JOIN il_space_booking（受影响订单/客户）；主对象=受影响订单；cancelStatus 为取消状态值（值域校准前置，缺省 ''1''）。', 'P0', 'ALERT', NULL, 'CHANGE', NULL, '[{"entity":"il_space_cancel","operations":["insert","update"],"role":"PRIMARY"}]', '{"steps":[{"name":"check","lang":"js","content":"const rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         bk.order_id AS biz_id, c.so_no AS biz_label,\\n         bk.customer_id AS customer_id, bk.customer_name AS customer_name,\\n         '''' AS owner_id, '''' AS owner_name,\\n         c.cancel_status AS cancel_status, c.booking_id AS booking_id, c.space_id AS space_id\\n  FROM ob.il_space_cancel c\\n  JOIN ob.il_space_booking bk ON bk.id = c.booking_id AND bk.del_status = 0\\n  WHERE c.del_status = 0\\n    AND c.id = :bizId\\n`, { ...$params, bizId: $ctx.bizId })\\nreturn rows.filter(r => r.cancel_status == $params.cancelStatus)"}]}', '{"cancelStatus":"1"}', '{"handlers":[{"type":"DEPT_ROLE","roleCode":"il_zgs_dingcang","org":{"scope":"BIZ_ORG"}}],"cc":[{"type":"DEPT_ROLE","roleCode":"il_fgs_czy","org":{"scope":"BIZ_ORG"}}]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 1, NULL, 1, 18, 'system', '系统初始化'),
('b1f1551aa2e3143c594b94a78225af6f', 'EXC-SLOT-004-E1', '船司甩柜/取消·1 级升级', 'SLOT', '升级规则：EXC-SLOT-004 在途且滞留 ≥ 4h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-SLOT-004', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-SLOT-004（改为扫描口径：取消记录全量），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         bk.order_id AS biz_id, c.so_no AS biz_label,\\n         bk.customer_id AS customer_id, bk.customer_name AS customer_name,\\n         '''' AS owner_id, '''' AS owner_name,\\n         c.cancel_status AS cancel_status, c.booking_id AS booking_id, c.space_id AS space_id\\n  FROM ob.il_space_cancel c\\n  JOIN ob.il_space_booking bk ON bk.id = c.booking_id AND bk.del_status = 0\\n  WHERE c.del_status = 0\\n    AND c.cancel_status = :cancelStatus\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-SLOT-004）----\\n  const base = r.cancel_status == $params.cancelStatus\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"cancelStatus":"1","escalateAfterHours":4}', '{"handlers":[{"type":"ORG_TREE_UP","level":1,"roleCode":"il_fgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'SPACE', NULL, 'STANDARD', '/fms/slot-contract/{bizId}', 1, NULL, 1, 19, 'system', '系统初始化'),
('37154b1af39f72acd3acbe4457ed641f', 'EXC-SLOT-004-E2', '船司甩柜/取消·2 级升级', 'SLOT', '升级规则：EXC-SLOT-004 在途且滞留 ≥ 8h（重算原条件仍成立）。\n命中动作：原 HANDLER 实例置 ESCALATED，生成新负责人实例并触达（每级对同一实例一次性生效）。', 'P0', 'ESCALATE', 'EXC-SLOT-004-E1', 'SCAN', '0 0/5 * * * *', NULL, '{"steps":[{"name":"escalate","lang":"js","content":"// 管道拷贝自 EXC-SLOT-004（改为扫描口径：取消记录全量），追加升级条件\\nconst rows = $sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         bk.order_id AS biz_id, c.so_no AS biz_label,\\n         bk.customer_id AS customer_id, bk.customer_name AS customer_name,\\n         '''' AS owner_id, '''' AS owner_name,\\n         c.cancel_status AS cancel_status, c.booking_id AS booking_id, c.space_id AS space_id\\n  FROM ob.il_space_cancel c\\n  JOIN ob.il_space_booking bk ON bk.id = c.booking_id AND bk.del_status = 0\\n  WHERE c.del_status = 0\\n    AND c.cancel_status = :cancelStatus\\n`, $params)\\nreturn rows.filter(r => {\\n  // ---- 原条件（拷贝自 EXC-SLOT-004）----\\n  const base = r.cancel_status == $params.cancelStatus\\n  // ---- 升级条件 ----\\n  const inst = $gl.target.targetInstance(r.biz_id)\\n  return base && inst != null && inst.status == ''OPEN''\\n      && $gl.fn.hoursSince(inst.firstAt) >= $params.escalateAfterHours\\n})"}]}', '{"cancelStatus":"1","escalateAfterHours":8}', '{"handlers":[{"type":"ORG_TREE_UP","level":2,"roleCode":"il_zgs_zjl"}],"cc":[{"type":"BIZ_FIELD"}]}', 'ANY', NULL, 'SPACE', NULL, 'STANDARD', '/fms/slot-contract/{bizId}', 1, NULL, 1, 20, 'system', '系统初始化');
